"use strict";(self.webpackChunkizakharau_blog_docusaurus=self.webpackChunkizakharau_blog_docusaurus||[]).push([[3785],{28453:(e,t,n)=>{n.d(t,{R:()=>s,x:()=>a});var i=n(96540);const o={},r=i.createContext(o);function s(e){const t=i.useContext(r);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:s(e.components),i.createElement(r.Provider,{value:t},e.children)}},33420:e=>{e.exports=JSON.parse('{"permalink":"/blog/spec-driven-development","source":"@site/blog/2026/spec-driven-development.md","title":"I dreamed about moving the requirements specification to code. Am I happy with Spec-Driven Development now?","description":"Spec-Driven Development promised to make requirements the center of software delivery. It did. Just not the way we expected.","date":"2026-05-19T00:00:00.000Z","tags":[{"inline":true,"label":"Product Management","permalink":"/blog/tags/product-management"},{"inline":true,"label":"Business Analysis","permalink":"/blog/tags/business-analysis"},{"inline":true,"label":"AI","permalink":"/blog/tags/ai"},{"inline":true,"label":"Requirements","permalink":"/blog/tags/requirements"}],"readingTime":4.13,"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"I dreamed about moving the requirements specification to code. Am I happy with Spec-Driven Development now?","description":"Spec-Driven Development promised to make requirements the center of software delivery. It did. Just not the way we expected.","date":"2026-05-19T00:00:00.000Z","slug":"spec-driven-development","tags":["Product Management","Business Analysis","AI","Requirements"],"keywords":["spec-driven development","SDD","requirements specification","docs-as-code","AI code generation","prompt engineering","context engineering","requirements engineering","business analysis AI","product management AI","OpenAPI","source of truth"],"image":"/img/2026/spec-driven-development.png"},"unlisted":false,"prevItem":{"title":"My Experience with AI-First Spec-Driven Development","permalink":"/blog/spec-driven-development-in-practice"},"nextItem":{"title":"AI Broke Product Planning and There Is No Obvious Way to Fix That","permalink":"/blog/ai-broke-product-planning"}}')},57382:(e,t,n)=>{n.d(t,{A:()=>i});const i=n.p+"assets/images/spec-driven-development-a86c26244e3bc43bf4c92eb584a57606.png"},99009:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>a,default:()=>p,frontMatter:()=>s,metadata:()=>i,toc:()=>d});var i=n(33420),o=n(74848),r=n(28453);const s={title:"I dreamed about moving the requirements specification to code. Am I happy with Spec-Driven Development now?",description:"Spec-Driven Development promised to make requirements the center of software delivery. It did. Just not the way we expected.",date:new Date("2026-05-19T00:00:00.000Z"),slug:"spec-driven-development",tags:["Product Management","Business Analysis","AI","Requirements"],keywords:["spec-driven development","SDD","requirements specification","docs-as-code","AI code generation","prompt engineering","context engineering","requirements engineering","business analysis AI","product management AI","OpenAPI","source of truth"],image:"/img/2026/spec-driven-development.png"},a=void 0,c={authorsImageUrls:[]},d=[];function l(e){const t={hr:"hr",img:"img",p:"p",...(0,r.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.p,{children:(0,o.jsx)(t.img,{alt:"cover",src:n(57382).A+"",width:"690",height:"390"})}),"\n",(0,o.jsx)(t.p,{children:"One problem with software development is (and still is) that related artifacts are distributed across various tools. Tasks are set in Jira, documentation in Confluence, and code in GitHub or GitLab. The requirements and documentation are unequivocally spread across those."}),"\n",(0,o.jsx)(t.p,{children:"If managed right, that is not a huge deal. Unfortunately, I rarely saw such cases in practice. Frequently, the requirements management on large enterprise projects goes rogue as soon as its initial owner/founder passes on. That contributes to a mental block that some developers had issues with (or simply don't like) reading requirements."}),"\n",(0,o.jsx)(t.p,{children:"And I could relate to that: the additional cognitive load of tracking all the task details from various sources and putting them into one picture. Plus, those requirements might be badly written. Some context might be missed, taken for granted, and so on."}),"\n",(0,o.jsx)(t.p,{children:"I understand those who ignore the specification and go directly to the source of truth or their proxy. Don't support, but understand."}),"\n",(0,o.jsx)(t.p,{children:"Fighting in the war for unification, I became an advocate for the docs-as-code approach where appropriate. Your service docs, as Markdown files, are under the same Git versioning as the source code. As a definition of done, the developer updates the docs along with the code. They no longer forget to update the docs. Plus, the docs are in code and are more clearly structured. At least, on my projects."}),"\n",(0,o.jsx)(t.p,{children:"That trick did not meet the requirement, though. I've never tried to implement that in practice; I only did a few thought experiments. My main issue is that, unlike the documentation, which aligns with the functional parts of an actual system, the requirements do not match the architectural design."}),"\n",(0,o.jsx)(t.p,{children:"Simply put, requirements may span multiple modules, so where the heck am I supposed to store them? And if they concern several repos? My thought experiment ended up with a separate Git repository for requirements, which is the worst idea, even compared to Confluence."}),"\n",(0,o.jsx)(t.p,{children:"Now, in 2026, docs are essential to the context for AI tools. So the proponents of docs-as-code had an advantage there, since they skipped a step involving Confluence MCP."}),"\n",(0,o.jsx)(t.p,{children:"AI also changes the perspective on requirements."}),"\n",(0,o.jsx)(t.p,{children:"The requirements specification quickly becomes irrelevant, regardless of the development work. Sometimes even quicker. And after that, the source code becomes the source of truth, the final outcome of the work."}),"\n",(0,o.jsx)(t.p,{children:"Now, code is disposable and can be easily regenerated by AI agents with a prompt and a single click. That shifts the industry to search for a source of truth elsewhere, something deterministic to rely on in the brave new undeterministic world."}),"\n",(0,o.jsx)(t.p,{children:"So, the Spec-Driven Development (SDD) approach takes the stage. And now everything is centered around the requirements. But it is not how we, the old guard of business analysis, expected it to be."}),"\n",(0,o.jsx)(t.hr,{}),"\n",(0,o.jsx)(t.p,{children:"Simply put, SDD is a paradigm where a structured specification drives code generation by AI agents. The approach itself is not new, as it has been widely used for interface definition and generation in formats such as OpenAPI and thousands of other Domain-Specific Languages."}),"\n",(0,o.jsx)(t.p,{children:"The spec is consumed by a machine that produces related code. The difference with AI is that the outcome is no longer deterministic, but the spec is. And the scale is different, as before, we could generate some layers using code generators. With AI agents, we can generate anything at any scale, limited only by the price of tokens."}),"\n",(0,o.jsx)(t.p,{children:"Developers no longer need to read requirements. They won. Kind of."}),"\n",(0,o.jsx)(t.hr,{}),"\n",(0,o.jsx)(t.p,{children:"Requirements engineering shifts to prompt and context engineering to put that machine-consumable contract into the black box and get the expected result. As much as expected, as is possible in its undeterministic nature."}),"\n",(0,o.jsx)(t.p,{children:"Now, requirements shall not be forgotten artifacts after the development is done. For large projects, it is essential to keep the spec as the source of truth, always up to date with the implementation, because it is the critical aspect of the context."}),"\n",(0,o.jsx)(t.p,{children:"To keep context concise, it is better to structure it and integrate it with the code (ideally with traceability). So my dream is coming true. Requirements move to code. Bye-bye Confluence and user stories in Jira."}),"\n",(0,o.jsx)(t.p,{children:"We can keep PRDs and BRDs for manager-humans to read for some time. But they'll likely put it into ChatGPT and ask it to summarize. Putting PRD into LLM for code generation, like all that vibecoding, is considered an antipattern. So those business-oriented artifacts, as we know them, may go away."}),"\n",(0,o.jsx)(t.hr,{}),"\n",(0,o.jsx)(t.p,{children:"Is that the future for requirements I was expecting? Obviously, not."}),"\n",(0,o.jsx)(t.p,{children:"But we live in strange times when companies try to ride the waves, imposing an illusion of control in the name of cost efficiency. And SDD was revived exactly for that purpose."}),"\n",(0,o.jsx)(t.p,{children:"There are dozens of tools like OpenSpec, MUSUBI, Spec-Kit, and Superpowers. In a year, the list might be entirely different."}),"\n",(0,o.jsx)(t.p,{children:"Oh, Brave New World!"})]})}function p(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(l,{...e})}):l(e)}}}]);